class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        return self.items.pop(0)

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

def find_min(values):
    min_value = values[0]
    for v in values:
        if v < min_value:
            min_value = v
    return min_value

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

def find_max(values):
    max_value = values[0]
    for v in values:
        if v > max_value:
            max_value = v
    return max_value

def is_palindrome(text):
    cleaned = text.lower().replace(' ', '')
    return cleaned == cleaned[::-1]

def rotate_list(items, k):
    k = k % len(items)
    return items[-k:] + items[:-k]

def deep_get(d, keys, default=None):
    for key in keys:
        if isinstance(d, dict) and key in d:
            d = d[key]
        else:
            return default
    return d

def word_count(text):
    counts = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def most_common(items):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return max(counts, key=counts.get)

def flatten(nested_list):
    result = []
    for item in nested_list:
        result.extend(item)
    return result

def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
